data.code:
features
    OnlineShop
        mandatory
            "Clothing Items" {abstract}
                optional
                    Shirts {size ['S', 'M', 'L', 'XL'], color ['Red', 'Blue', 'Green', 'Black', 'White']}
                    Pants {size ['S', 'M', 'L', 'XL'], color ['Red', 'Blue', 'Green', 'Black', 'White']}
                    Dresses {size ['XS', 'S', 'M', 'L', 'XL'], color ['Red', 'Blue', 'Green', 'Black', 'White', 'Pink']}
        mandatory
            "Payment Options" {abstract}
                alternative
                    CreditCard
                    DebitCard
                    CashOnDelivery

features
    Sofa
        mandatory
            MainFabric
                alternative
                    SmoothLeather {Color 'beige'}
                    RoughTweed {Color 'charcoal'}
                    SoftVelvet {Color 'emerald'}
            Legs
                alternative
                    SleekChromeLegs {Style 'modern'}
                    NaturalOakWoodLegs {Style 'classic'}
                    PaintedBlackLegs {Style 'industrial'}
            Cushions
                alternative
                    FirmCushions {Support true}
                    SoftCushions {Plush true}

features
    "Cloud Storage Plan" {abstract}
        mandatory
            "Storage Amount" {abstract}
                alternative
                    "100GB Storage" {capacity '100GB', useCase 'personal'}
                    "1TB Storage" {capacity '1TB', useCase 'small business'}
            "Allowed Users" {abstract}
                alternative
                    "Single User Plan" {maxUsers 1}
                    "Up to Five Team Members" {maxUsers 5}
                    "Unlimited Enterprise Users" {maxUsers -1}
            "Security Features" {abstract}
                mandatory
                    "Standard Encryption"
                optional
                    "Two-factor Authentication"
                    "GDPR Compliance"

features
    BankAccounts
        mandatory
            Deposit
            Withdraw
        alternative
            CheckingAccount {Purpose 'Everyday Transactions', Access 'Easy', InterestRate 0}
                optional
                    OverdraftProtection
            SavingsAccount {Purpose 'Grow Money', HasInterest true, WithdrawalLimits true}
                optional
                    HighYieldAccount {InterestRate 3.5, MinimumBalance 1000}
            StudentAccount {MonthlyFee 0, MinimumBalance 50, TargetAudience 'Students'}

features
    Mortgage
        mandatory
            "Rate Type"
                alternative
                    "Fixed Rate" {rate_stability 'fixed'}
                    "Variable Rate" {rate_stability 'variable'}
            "Term Length"
                alternative
                    "1 Year Term" {initial_rate 'lower', renegotiate_frequency 'more_often'}
                    "3 Year Term"
                    "5 Year Term" {payment_stability 'more_stability'}
            "Amortization Period"
                alternative
                    "20 Years Amortization" {monthly_payments 'higher', total_interest_paid 'less'}
                    "25 Years Amortization"
                    "30 Years Amortization" {monthly_payments 'smaller', total_interest_paid 'more'}

features
    InsurancePolicy
        mandatory
            Deductible {Amount 500}
        optional
            CarInsurance
                mandatory
                    VehicleDamageLimit {Amount 50000}
        optional
            RoadsideAssistance {AdditionalFee true}
        optional
            RentalCarCoverage {AdditionalFee true}

features
    Tickets
        mandatory
            "Seating Section"
                alternative
                    "General Admission Standing" {price 30.0}
                    "Front Rows Reserved" {price 80.0}
                    "Balcony Reserved" {price 60.0}
        optional
            "VIP Access"
                alternative
                    "Basic VIP Package" {price 50.0, benefits ['Early Entry']}
                    "Premium VIP Package" {price 120.0, benefits ['Early Entry', 'Special Lounge']}
                    "Ultimate VIP Package" {price 250.0, benefits ['Early Entry', 'Special Lounge', 'Backstage Pass']}
        optional
            "Ticket Insurance"
                alternative
                    "Standard Policy" {price 10.0}
                    "Premium Policy" {price 25.0}
